namespace war3 {
void GameData::prepareConsole() {
    FrameDefinitions definitions;auto& archives=assets->resources();definitions.load(archives,"UI\\FrameDef\\UI\\ConsoleUI.fdf");auto frame=definitions.frame("ConsoleUI");auto local=session->localPlayer().value_or(0);auto race=session->config().players[local].race;std::string name=race==2?"Orc":race==3?"Undead":race==4?"NightElf":"Human";
    for(auto& piece:frame.children)if(piece.type=="TEXTURE"){auto& file=piece.property("File");auto& uv=piece.property("TexCoord");auto& anchor=piece.property("Anchor");if(file.size()!=1 || uv.size()!=4 || anchor.size()!=3 || !file[0].starts_with("ConsoleTexture"))throw std::runtime_error("Unsupported source console texture layout");float w=piece.number("Width"),h=piece.number("Height"),dx=std::stof(anchor[1]),dy=std::stof(anchor[2]);float x=anchor[0].ends_with("LEFT")?dx:.8f+dx-w,y=anchor[0].starts_with("TOP")?-dy:.6f-dy-h;auto member="UI\\Console\\"+name+"\\"+name+"UITile"+file[0].substr(14)+".blp";assets->image(member);console.push_back({x,y,w,h,std::stof(uv[0]),std::stof(uv[2]),std::stof(uv[1]),std::stof(uv[3]),member});}
    if(console.size()!=9)throw std::runtime_error("Source console requires nine texture pieces");unsigned i=0;for(auto label:{"Gold","Lumber","Supply"}){resourceIcons[i]="UI\\Feedback\\Resources\\Resource"+std::string(label)+".blp";assets->image(resourceIcons[i++]);}
    for(auto size:{"Small","Med","Large"})assets->image("ReplaceableTextures\\Selection\\SelectionCircle"+std::string(size)+".blp");
    assets->image("ReplaceableTextures\\Selection\\SpellAreaOfEffect.blp");autocastModel=skinValue(archives,"CommandButtonAutocast","UI\\Feedback\\Autocast\\UI-ModalButtonOn.mdl");
    SourceSettings commandSource;commandSource.load(archives,"Units\\CommandFunc.txt");commandSource.load(archives,"Units\\CommandStrings.txt");auto loadCommand=[&](const char* section,GameCommand& button){auto art=commandSource.value(section,"Art");if(art.empty())throw std::runtime_error(std::string("Missing source command art: ")+section);button.icon=skinValue(archives,art,art);if(button.icon.empty() || button.icon=="_")throw std::runtime_error(std::string("Missing source command icon: ")+section);auto position=commandSource.value(section,"Buttonpos");auto comma=position.find(',');if(comma==std::string::npos)throw std::runtime_error(std::string("Missing source command position: ")+section);auto parse=[&](std::string_view value){value.remove_prefix(std::min(value.find_first_not_of(" \t"),value.size()));value.remove_suffix(value.size()-std::min(value.find_last_not_of(" \t")+1,value.size()));unsigned result=0;auto [end,error]=std::from_chars(value.data(),value.data()+value.size(),result);if(error!=std::errc{} || end!=value.data()+value.size() || result>3)throw std::runtime_error(std::string("Invalid source command position: ")+section);return result;};button.x=parse(std::string_view(position).substr(0,comma));button.y=parse(std::string_view(position).substr(comma+1));if(button.y>2)throw std::runtime_error(std::string("Invalid source command row: ")+section);button.hotkey=commandSource.value(section,"Hotkey");button.name=commandSource.value(section,"Tip",section);button.tip=commandSource.value(section,"Ubertip",button.name);assets->image(button.icon);};i=0;for(auto section:{"CmdAttack","CmdMove","CmdStop","CmdHoldPos","CmdPatrol"})loadCommand(section,commands[i++]);i=0;for(auto section:{"CmdBuildHuman","CmdBuildOrc","CmdBuildUndead","CmdBuildNightElf"})loadCommand(section,buildCommands[i++]);loadCommand("CmdCancel",cancelCommand);loadCommand("CmdCancelBuild",cancelBuildCommand);loadCommand("CmdSelectSkill",selectSkillCommand);
    if(auto member=archives.readCandidates({"war3mapMap.blp"},ArchiveScope::Map)){minimap="war3mapMap.blp";assets->image(minimap);}for(auto& [handle,unit]:session->units()){auto path=unit->icon;auto comma=path.find(',');if(comma!=std::string::npos)path.resize(comma);if(!path.empty() && path!="_"){assets->image(path);}}
}
bool GameData::uploadOne(Renderer& renderer) {if(assets->uploadOne(renderer))return true;if(terrain->uploadOne(renderer))return true;return false;}
GameLoading::GameLoading(Log& log) : log_(log),worker_([this](std::stop_token stop){run(stop);}) {}
GameLoading::~GameLoading() {{std::lock_guard lock(mutex_);worker_.request_stop();++generation_;}wake_.notify_one();}
std::uint64_t GameLoading::request(std::unique_ptr<ScriptSession> session) {if(!session || !session->configured() || !session->world())throw std::runtime_error("Cannot start unconfigured map");std::lock_guard lock(mutex_);auto id=++generation_;pending_=Request{id,std::move(session)};ready_.reset();phase_=0;wake_.notify_one();return id;}
void GameLoading::cancel() {std::lock_guard lock(mutex_);++generation_;pending_.reset();ready_.reset();}
std::optional<GameLoadResult> GameLoading::poll() {std::lock_guard lock(mutex_);auto result=std::move(ready_);ready_.reset();return result;}
void GameLoading::run(std::stop_token stop) {
    while(!stop.stop_requested()){Request request;{std::unique_lock lock(mutex_);wake_.wait(lock,[&]{return stop.stop_requested() || pending_.has_value();});if(stop.stop_requested())return;request=std::move(*pending_);pending_.reset();}auto started=GetTickCount64();auto stale=[&]{return stop.stop_requested() || generation_.load()!=request.id;};GameLoadResult result;result.request=request.id;
        try{auto game=std::make_unique<GameData>();game->session=std::move(request.session);auto checkpoint=[&,id=request.id]{if(stop.stop_requested() || generation_.load()!=id)throw std::runtime_error("Map load canceled");};checkpoint();phase_=1;game->session->startMain();checkpoint();phase_=2;game->assets=std::make_unique<SceneAssets>(game->session->world()->resources(),checkpoint);game->terrain=std::make_unique<TerrainScene>(*game->session->world(),*game->assets,log_);checkpoint();phase_=3;game->objects=std::make_unique<SceneObjects>(*game->session,*game->assets,log_);checkpoint();phase_=4;game->prepareConsole();game->assets->model(game->autocastModel,log_);if(!game->session->world()->environment().skyModel.empty())game->assets->model(game->session->world()->environment().skyModel,log_);for(auto& [id,item]:game->session->items())if(!item->icon.empty() && item->icon!="_")game->assets->image(item->icon);checkpoint();game->assets->clearCheck();if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll must not be loaded");log_.write("game_cpu_ready elapsed_ms="+std::to_string(GetTickCount64()-started)+" textures="+std::to_string(game->assets->uploadCount())+" chunks="+std::to_string(game->terrain->uploadCount())+" units="+std::to_string(game->session->units().size())+" game_dll_loaded=false");result.data=std::move(game);
        }catch(const std::exception& e){result.error=e.what();if(!stale())log_.write("game_load_failed="+result.error);}std::lock_guard lock(mutex_);if(!stale())ready_=std::move(result);
    }
}
}
